Lemma kept_ok_of_regs_agree : forall (clob : list reg) regs regs',
  (forall r, In r clob -> In (AX2.ridx r) AP.caller_saved) ->
  regs_agree (fun r => In r clob) regs regs' -> APSX.kept_ok regs regs'.
Proof.
ltac2:(KReplay.run1 (kr_t_SumsSpecLib ()) [] "h01rh13Hagh23Hinh34Hninh43Hr0h54Hsubh64clobh74regsh85regs'p;1p;2p;3g0000j10Tg000Uj1<Tg001:j13Tg001Xj14Tg002;j1;Tg002[j2:Tg003Gj31Tg003^j18Tg004lj37Tg0067j36Tg006Zj35Tg0074j12Tg007Mj29Tg008f#0R0#<#3R1#4R2#;%00#0#0#0#0#3#4,:1R0f0R3f3R4512g009Kf1R5#8g009j31R6[^02f49123X02f2R7;75g00;=g00;[5619523#2%26P4P7f79127R6P5f5P4P3O2O1W2%26eO2W3W4X021947eW1W5X80W7W6o"). Qed.

Ltac in_list := cbn [In]; repeat (first [left; (reflexivity || (apply bv_eq; reflexivity)) | right]).

Ltac clob_sub :=
  let r := fresh "r" in let H := fresh "H" in
  intros r H; cbn [In] in H;
  repeat (destruct H as [<-|H]; [in_list|]); destruct H.

